import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, ActivatedRoute } from '@angular/router';
import { ApiService } from '../../../core/services/api.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-tour-detail',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div *ngIf="tour" class="fade-in">
      <div class="detail-hero">
        <img [src]="tour.images?.[0]?.url || tour.imageUrl || 'https://picsum.photos/seed/' + tour.slug + '/1200/600'" [alt]="tour.name">
        <div class="detail-hero-overlay">
          <div class="container">
            <h1>{{ tour.name }}</h1>
            <p><span class="material-icons">schedule</span> {{ tour.duration }} | {{ tour.maxPeople }} người</p>
            <div class="pricing-hero">
              <span class="old" *ngIf="tour.discountPrice">{{ tour.price | number:'1.0-0' }}đ</span>
              <span class="current">{{ (tour.discountPrice || tour.price) | number:'1.0-0' }}đ</span>
              <span class="per">/người</span>
            </div>
          </div>
        </div>
      </div>
      <section class="section">
        <div class="container">
          <div class="detail-layout">
            <div class="detail-main">
              <div class="content-section">
                <h2>Mô tả</h2>
                <p>{{ tour.description }}</p>
              </div>
              <div class="content-section" *ngIf="tour.includes">
                <h2>Bao gồm</h2>
                <ul class="includes-list">
                  <li *ngFor="let item of getIncludes()"><span class="material-icons">check</span> {{ item }}</li>
                </ul>
              </div>
              <div class="content-section" *ngIf="tour.schedules?.length">
                <h2>Lịch trình</h2>
                <div class="schedule">
                  <div *ngFor="let s of tour.schedules" class="schedule-item">
                    <div class="schedule-header">
                      <span class="day">Ngày {{ s.day }}</span>
                      <span class="time">{{ s.time }}</span>
                    </div>
                    <h4>{{ s.title }}</h4>
                    <p>{{ s.description }}</p>
                    <p *ngIf="s.location" class="location"><span class="material-icons">location_on</span> {{ s.location }}</p>
                  </div>
                </div>
              </div>
            </div>
            <div class="detail-sidebar">
              <div class="booking-card card">
                <div class="card-body">
                  <div class="price-display">
                    <span class="old" *ngIf="tour.discountPrice">{{ tour.price | number:'1.0-0' }}đ</span>
                    <span class="current">{{ (tour.discountPrice || tour.price) | number:'1.0-0' }}đ</span>
                    <span class="per">/người</span>
                  </div>
                  <div class="info-row"><span class="material-icons">schedule</span> {{ tour.duration }}</div>
                  <div class="info-row"><span class="material-icons">group</span> Tối đa {{ tour.maxPeople }} người</div>
                  <button class="btn btn-accent btn-lg" style="width:100%;" routerLink="/contact">
                    <span class="material-icons">support_agent</span>
                    Yêu cầu đặt tour
                  </button>
                  <a class="btn btn-outline" style="width:100%;margin-top:0.5rem;" routerLink="/contact">
                    <span class="material-icons">chat</span>
                    Tư vấn thêm
                  </a>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
    <div class="loading-spinner" *ngIf="!tour"><div class="spinner"></div></div>
  `,
  styles: [`
    .pricing-hero { display: flex; align-items: baseline; gap: 0.75rem; margin-top: 0.5rem; .old { text-decoration: line-through; font-size: 1.125rem; opacity: 0.7; } .current { font-size: 2rem; font-weight: 700; color: #f59e0b; } }
    .detail-layout { display: grid; grid-template-columns: 1fr 340px; gap: 2rem; @media(max-width:768px){grid-template-columns:1fr;} }
    .content-section { margin-bottom: 2rem; h2 { font-size: 1.5rem; margin-bottom: 1rem; padding-bottom: 0.5rem; border-bottom: 2px solid #e2e8f0; } }
    .includes-list { display: grid; grid-template-columns: repeat(2,1fr); gap: 0.5rem; list-style: none; margin: 0; padding: 0; li { display: flex; align-items: center; gap: 0.5rem; .material-icons { color: var(--secondary); font-size: 1.125rem; } } }
    .schedule { display: flex; flex-direction: column; gap: 1rem; }
    .schedule-item { background: var(--light); border-radius: var(--border-radius-sm); padding: 1.25rem; }
    .schedule-header { display: flex; gap: 0.75rem; margin-bottom: 0.5rem; .day { font-weight: 700; color: var(--primary); } .time { color: var(--gray); font-size: 0.875rem; } }
    .schedule-item h4 { margin-bottom: 0.5rem; }
    .schedule-item .location { display: flex; align-items: center; gap: 0.25rem; color: var(--gray); font-size: 0.875rem; .material-icons { font-size: 1rem; } }
    .booking-card { position: sticky; top: 90px; }
    .price-display { display: flex; align-items: baseline; gap: 0.5rem; margin-bottom: 1rem; .old { text-decoration: line-through; color: var(--gray-light); } .current { font-size: 1.75rem; font-weight: 700; color: var(--danger); } }
    .info-row { display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0; border-bottom: 1px solid #f1f5f9; .material-icons { color: var(--gray); font-size: 1.25rem; } }
  `]
})
export class TourDetailComponent implements OnInit {
  tour: any = null;
  constructor(private api: ApiService, private route: ActivatedRoute) {}
  ngOnInit() {
    const slug = this.route.snapshot.paramMap.get('slug') || this.route.snapshot.paramMap.get('id') || '';
    this.api.getTour(slug).subscribe(data => { this.tour = data; });
  }
  getIncludes(): string[] { try { return JSON.parse(this.tour?.includes || '[]'); } catch { return []; } }
}
